from collections import deque
R=C=30; seen=set(); comps={}; labgrid={}
for r in range(R):
 for c in range(C):
  if grid[r][c] and (r,c) not in seen:
   q=deque([(r,c)]);seen.add((r,c)); pts=[]
   while q:
    p=q.popleft();pts.append(p)
    for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)):
     z=(p[0]+dr,p[1]+dc)
     if 0<=z[0]<R and 0<=z[1]<C and grid[z[0]][z[1]] and z not in seen: seen.add(z);q.append(z)
   comps[len(comps)+1]=pts
   for p in pts: labgrid[p]=len(comps)
seeds={v:next((r,c) for r in range(R) for c in range(C) if grid[r][c]==v) for v in (4,8,6)}
print(seeds,{v:labgrid[p] for v,p in seeds.items()})
centers=[]
for r in range(1,R-1):
 for c in range(1,C-1):
  if all(grid[i][j] for i in range(r-1,r+2) for j in range(c-1,c+2)):
   centers.append((r,c,labgrid[(r,c)]))
for v,p in seeds.items(): print(v,[(r,c) for r,c,l in centers if l==labgrid[p]])

out=[row[:] for row in grid]
for r,c,l in centers:
 for color,p in seeds.items():
  if l==labgrid[p] and out[r][c]==1: out[r][c]=color
import json
print(json.dumps({'action':'submit','grid':out},separators=(',',':')))
